# compounds BERT large — batch 4096, lr 5.31e-04
# The compounds batch-size grid of the 2026-11-19c, 2026-11-20 and 2026-11-27b directives. Generated by
# scripts/compounds_batch_sweep_configs.py from the derived arm inventory; edit the
# inventory and regenerate rather than editing this file.
#
# This arm's place in the grid. BERT runs 3 rates at this size and batch and keeps the lowest (§3); this is number 2 of 3, against 3.79e-04, 7.59e-04.
#
# The budget is fixed in columns, not in steps (§2): 115,200,000 packed blocks of
# 1024 tokens = 117,964,800,000 tokens, the same for all 90 BERT
# arms. At batch 4096 that is 28,125 steps, so the five batches cover the
# same data and their curves are compared at the same column.
#
# The rate is this size's 2,560 rate scaled by sqrt(batch/2560) (§3): 2.80 x sqrt(4096/2560) x this size's 2,560 rate = 5.31e-04.
#
# Warmup is 10 % of this arm's own length (§4), truncated: 2,812 of
# 28,125. The decay shape is the one the existing ladder uses.
#
# One GPU takes 64 columns and the accumulation count carries the rest (the
# micro-batch directive of 2026-11-19, which replaces 19c §8, repeated for batch 256
# by the 2026-11-20 directive):
# 64 x 16 x 4 GPUs = 4096. Held across the five batches, so what differs between them is the accumulation count and nothing else.
#
# Evaluation is fixed, not redrawn (§6): the same 10,000 rows, the same masked
# positions, the same grouping into batches on all 90 BERT arms. fixed_eval_mask
# reseeds from the batch's own bytes mixed with eval_mask_seed, so the positions only
# repeat when the rows are grouped the same way -- which is why the evaluation
# micro-batch and the GPU count are held at 32 and 4 across the
# grid rather than following the training batch.
#
# The judged metric is eval_loss_mask (2026-11-20 §2, which replaces 19c §7), and
# retention follows the same metric. eval_loss itself and the rest of the
# per-position breakdown are still computed, still logged at every evaluation and
# still go into the reported TSV; they are not what the arm is ranked on.

from molcrawl.data.compounds.utils.tokenizer import CompoundsTokenizer as Tokenizer
from molcrawl.core.paths import COMPOUNDS_DATASET_DIR_BERT, get_bert_output_path

tokenizer = Tokenizer("assets/molecules/vocab.txt", 256)

model_size = "large"
# Per-arm directory under MODEL_OUTPUT_ROOT. Unset, this resolves under
# LEARNING_SOURCE_DIR -- the tree compounds' input and output already share -- and
# main.py's output guard stops the run before the first step.
model_path = get_bert_output_path("compounds", model_size) + "-b4096-lr5p31e4"
dataset_dir = COMPOUNDS_DATASET_DIR_BERT
max_length = 1024  # packed blocks; sets BertConfig.max_position_embeddings

max_steps = 28125
warmup_steps = 2812  # 10 % of max_steps (§4)
learning_rate = 0.000531
weight_decay = 0.01
# Pretraining runs the whole schedule (§4): a stop part-way would leave the four
# curves different lengths and nothing to compare.
early_stopping = False

# 225 evaluation points and 45 save points, at the same column
# positions as every other batch in the grid (§2). save_steps is a multiple of the
# evaluation interval, so every checkpoint carries an evaluation.
log_interval = 125  # = eval_steps
save_steps = 625

# Keep the checkpoint the reported number came from: the minimum lands off the save
# grid most of the time, and the arm would otherwise be ranked on a number whose
# weights no longer exist.
save_on_improve = True

# The judged metric, and the same metric for the kept checkpoint (2026-11-20 §2).
judge_on = "eval_loss_mask"
metric_for_best_model = "eval_loss_mask"
save_on_improve_metric = "eval_loss_mask"
checkpoint_metric = "eval_loss_mask"

# The same masked positions at every evaluation, on every arm (§6).
fixed_eval_mask = True
eval_mask_seed = 42
# The compounds sets were packed in source order before the 2026-08-21 rebuild, so the
# split's leading rows are shorter and easier than the split as a whole. Draw the eval
# subset at random instead.
#
# The subset seed is deliberately NOT written here. The rows come from one constant,
# EVAL_SUBSET_SEED in models/bert/main.py, which is already the 42 §6
# asks for; a config that declared it would be the thing that could move one arm's
# rows away from the others, and tests/unit/test_bert_eval_subset.py refuses any
# config in the tree that names it.
eval_subset_random = True
# Held at 32 on all 90 arms, independent of the training batch: it decides how
# the rows are grouped, and therefore which positions are masked. 32 is the
# largest value xl is on record as running at, so no arm needs an untried one.
per_device_eval_batch_size = 32

# Stop an arm that has fallen into the degenerate solution instead of letting it spend
# the rest of a long schedule there. 2.4733 is the degenerate floor measured for
# this corpus.
degenerate_loss_threshold = 2.4733
# How long to wait before the rule above can fire. MLM sits at the degenerate
# level for a while at the start, so a short wait reads that plateau as a collapse.
# The wait is a number of blocks, not a number of steps, so every batch waits over
# the same amount of data (2026-11-27 judgment §4): 11,520,000 blocks, 10 % of the
# budget, which at batch 4096 is 2,812 of this arm's 28,125 steps
# (11,517,952 blocks once truncated, as the warmup is).
degenerate_grace_steps = 2812

# Confine attention to one document inside a packed block; without it a masked token
# attends across document boundaries.
document_masking = True

# 64 x 16 x 4 GPUs = 4096 (micro-batch directive §1).
batch_size = 64
gradient_accumulation_steps = 16
# Declared so main.py stops a launch whose GPU count would build another batch (§5).
expected_global_batch = 4096

# The grid writes every key out rather than importing bert_large.py, so nothing added
# to the base reaches it. Same values as every BERT base: four dataloader workers into
# pinned buffers, and bf16. A grid must not mix worker counts across its arms -- the
# worker count changes the masked positions.
dataloader_num_workers = 4
dataloader_pin_memory = True
bf16 = True

# seed 42 per the standing directive (§9). data_seed is not written: neither path
# reads it and both refuse a config that declares one different from seed.
seed = 42

# HF's own default, stated here so the window is a choice rather than a leftover. It
# covers the largest checkpoint write on record and is deliberately not longer: the
# rank divergences of 2026-10-16 and 2026-10-19 were not cured by a wider window, they
# were only reported later.
ddp_timeout = 1800
